public class DistributedJobExecutor {
    private final DataSource dataSource;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(4);

    public void startPolling(String workerId, long intervalMillis) {
        scheduler.scheduleAtFixedRate(() -> {
            try (Connection conn = dataSource.getConnection()) {
                conn.setAutoCommit(false);
                try (PreparedStatement pstmt = conn.prepareStatement(
                        "SELECT job_id, payload FROM scheduled_jobs WHERE status = 'PENDING' " +
                        "AND next_execution <= ? LIMIT 1 FOR UPDATE SKIP LOCKED")) {

                    pstmt.setTimestamp(1, new Timestamp(System.currentTimeMillis()));
                    try (ResultSet rs = pstmt.executeQuery()) {
                        if (rs.next()) {
                            long jobId = rs.getLong("job_id");
                            String payload = rs.getString("payload");

                            claimAndExecuteJob(conn, jobId, workerId, payload);
                        }
                    }
                }
            } catch (Exception e) {
                // Log and monitor scheduler acquisition exceptions
            }
        }, 0, intervalMillis, TimeUnit.MILLISECONDS);
    }

    private void claimAndExecuteJob(Connection conn, long jobId, String workerId, String payload) throws SQLException {
        try (PreparedStatement update = conn.prepareStatement(
                "UPDATE scheduled_jobs SET status = 'RUNNING', locked_by = ? WHERE job_id = ?")) {
            update.setString(1, workerId);
            update.setLong(2, jobId);
            update.executeUpdate();
            conn.commit();

            // Execute asynchronous task payload
            CompletableFuture.runAsync(() -> processPayload(payload));
        }
    }

    private void processPayload(String payload) {
        // Business logic execution boundary
    }
}
